    70→export async function downloadByRoot({
    71→  config,
    72→  seenCache,
    73→  network,
    74→  emitter,
    75→  peerMeta,
    76→  cacheItem,
    77→}: DownloadByRootProps): Promise<WarnResult<PendingBlockInput, DownloadByRootError>> {
    78→  const rootHex = getBlockInputSyncCacheItemRootHex(cacheItem);
    79→  const blockRoot = fromHex(rootHex);
    80→  const {peerId: peerIdStr} = peerMeta;
    81→
    82→  const {
    83→    result: {block, blobSidecars, columnSidecars},
    84→    warnings,
    85→  } = await fetchByRoot({
    86→    config,
    87→    network,
    88→    cacheItem,
    89→    blockRoot,
    90→    peerMeta,
    91→  });
    92→
    93→  let blockInput: IBlockInput;
    94→  if (isPendingBlockInput(cacheItem)) {
    95→    blockInput = cacheItem.blockInput;
    96→    if (!blockInput.hasBlock()) {
    97→      blockInput.addBlock({
    98→        block,
    99→        blockRootHex: rootHex,
   100→        source: BlockInputSource.byRoot,
   101→        seenTimestampSec: Date.now() / 1000,
   102→        peerIdStr,
   103→      });
   104→    }
   105→  } else {
   106→    blockInput = seenCache.getByBlock({
   107→      block,
   108→      peerIdStr,
   109→      blockRootHex: rootHex,
   110→      seenTimestampSec: Date.now() / 1000,
   111→      source: BlockInputSource.byRoot,
   112→    });
   113→  }
   114→
   115→  const hasAllDataPreDownload = blockInput.hasBlockAndAllData();
   116→
   117→  if (isBlockInputBlobs(blockInput) && !hasAllDataPreDownload) {
   118→    // blobSidecars could be undefined if gossip resulted in full block+blobs so we don't download any
   119→    if (!blobSidecars) {
   120→      throw new DownloadByRootError({
   121→        code: DownloadByRootErrorCode.MISSING_BLOB_RESPONSE,
   122→        blockRoot: prettyBytes(rootHex),
   123→        peer: peerIdStr,
   124→      });
   125→    }
   126→    for (const blobSidecar of blobSidecars) {
   127→      if (blockInput.hasBlob(blobSidecar.index)) {
   128→        // the same BlobSidecar may be added by gossip while waiting for fetchByRoot
   129→        // TODO(fulu): add metric here to track this
   130→        continue;
   131→      }
   132→
   133→      blockInput.addBlob({
   134→        blobSidecar,
   135→        blockRootHex: rootHex,
   136→        seenTimestampSec: Date.now() / 1000,
   137→        source: BlockInputSource.byRoot,
   138→        peerIdStr,
   139→      });
   140→
   141→      if (emitter.listenerCount(routes.events.EventType.blobSidecar)) {
   142→        const versionedHashes = blockInput.getVersionedHashes();
   143→
   144→        emitter.emit(routes.events.EventType.blobSidecar, {
   145→          blockRoot: rootHex,
   146→          slot: blockInput.slot,
   147→          index: blobSidecar.index,
   148→          kzgCommitment: toHex(blobSidecar.kzgCommitment),
   149→          versionedHash: toHex(versionedHashes[blobSidecar.index]),
   150→        });
   151→      }
   152→    }
   153→  }
   154→
   155→  if (isBlockInputColumns(blockInput) && !hasAllDataPreDownload) {
   156→    // columnSidecars could be undefined if gossip resulted in full block+columns so we don't download any
   157→    if (!columnSidecars) {
   158→      throw new DownloadByRootError({
   159→        code: DownloadByRootErrorCode.MISSING_COLUMN_RESPONSE,
   160→        blockRoot: prettyBytes(rootHex),
   161→        peer: peerIdStr,
   162→      });
   163→    }
   164→    for (const columnSidecar of columnSidecars) {
   165→      if (blockInput.hasColumn(columnSidecar.index)) {
   166→        // the same DataColumnSidecar may be added by gossip while waiting for fetchByRoot
   167→        // TODO(fulu): add metric here to track this
   168→        continue;
   169→      }
   170→
   171→      blockInput.addColumn({
   172→        columnSidecar,
   173→        blockRootHex: rootHex,
   174→        seenTimestampSec: Date.now() / 1000,
   175→        source: BlockInputSource.byRoot,
   176→        peerIdStr,
   177→      });
   178→
   179→      if (emitter.listenerCount(routes.events.EventType.dataColumnSidecar)) {
   180→        emitter.emit(routes.events.EventType.dataColumnSidecar, {
   181→          blockRoot: rootHex,
   182→          slot: blockInput.slot,
   183→          index: columnSidecar.index,
   184→          kzgCommitments: columnSidecar.kzgCommitments.map(toHex),
   185→        });
   186→      }
   187→    }
   188→  }
   189→
   190→  let status: PendingBlockInputStatus;
   191→  let timeSyncedSec: number | undefined;
   192→  if (blockInput.hasBlockAndAllData()) {
   193→    status = PendingBlockInputStatus.downloaded;
   194→    timeSyncedSec = Date.now() / 1000;
   195→  } else {
   196→    status = PendingBlockInputStatus.pending;
   197→  }
   198→
   199→  return {
   200→    result: {
   201→      status,
   202→      blockInput,
   203→      timeSyncedSec,
   204→      timeAddedSec: cacheItem.timeAddedSec,
   205→      peerIdStrings: cacheItem.peerIdStrings,
   206→    },
   207→    warnings,
   208→  };
   209→}
