   211→export async function fetchByRoot({
   212→  config,
   213→  network,
   214→  peerMeta,
   215→  blockRoot,
   216→  cacheItem,
   217→}: FetchByRootProps): Promise<WarnResult<FetchByRootResponses, DownloadByRootError>> {
   218→  let block: SignedBeaconBlock;
   219→  let blobSidecars: deneb.BlobSidecars | undefined;
   220→  let columnSidecarResult: WarnResult<fulu.DataColumnSidecars, DownloadByRootError> | undefined;
   221→  const {peerId: peerIdStr} = peerMeta;
   222→
   223→  if (isPendingBlockInput(cacheItem)) {
   224→    if (cacheItem.blockInput.hasBlock()) {
   225→      block = cacheItem.blockInput.getBlock();
   226→    } else {
   227→      block = await fetchAndValidateBlock({
   228→        config,
   229→        network,
   230→        peerIdStr,
   231→        blockRoot,
   232→      });
   233→    }
   234→
   235→    const forkName = config.getForkName(block.message.slot);
   236→    if (!cacheItem.blockInput.hasAllData()) {
   237→      if (isBlockInputBlobs(cacheItem.blockInput)) {
   238→        blobSidecars = await fetchAndValidateBlobs({
   239→          config,
   240→          network,
   241→          peerIdStr,
   242→          forkName: forkName as ForkPreFulu,
   243→          block: block as SignedBeaconBlock<ForkPostDeneb>,
   244→          blockRoot,
   245→          missing: cacheItem.blockInput.getMissingBlobMeta().map(({index}) => index),
   246→        });
   247→      }
   248→      if (isBlockInputColumns(cacheItem.blockInput)) {
   249→        columnSidecarResult = await fetchAndValidateColumns({
   250→          config,
   251→          network,
   252→          peerMeta,
   253→          forkName: forkName as ForkPostFulu,
   254→          block: block as SignedBeaconBlock<ForkPostFulu>,
   255→          blockRoot,
   256→          missing: cacheItem.blockInput.getMissingSampledColumnMeta().missing,
   257→        });
   258→      }
   259→    }
   260→  } else {
   261→    block = await fetchAndValidateBlock({
   262→      config,
   263→      network,
   264→      peerIdStr,
   265→      blockRoot,
   266→    });
   267→    const forkName = config.getForkName(block.message.slot);
   268→    if (isForkPostFulu(forkName)) {
   269→      columnSidecarResult = await fetchAndValidateColumns({
   270→        config,
   271→        network,
   272→        peerMeta,
   273→        forkName,
   274→        blockRoot,
   275→        block: block as SignedBeaconBlock<ForkPostFulu>,
   276→        missing: network.custodyConfig.sampledColumns,
   277→      });
   278→    } else if (isForkPostDeneb(forkName)) {
   279→      const commitments = (block as SignedBeaconBlock<ForkPostDeneb & ForkPreFulu>).message.body.blobKzgCommitments;
   280→      const blobCount = commitments.length;
   281→      blobSidecars = await fetchAndValidateBlobs({
   282→        config,
   283→        network,
   284→        peerIdStr,
   285→        forkName: forkName as ForkPreFulu,
   286→        blockRoot,
   287→        block: block as SignedBeaconBlock<ForkPostDeneb>,
   288→        missing: Array.from({length: blobCount}, (_, i) => i),
   289→      });
   290→    }
   291→  }
   292→
   293→  return {
   294→    result: {
   295→      block,
   296→      blobSidecars,
   297→      columnSidecars: columnSidecarResult?.result,
   298→    },
   299→    warnings: columnSidecarResult?.warnings ?? null,
   300→  };
   301→}
