   303→export async function fetchAndValidateBlock({
   304→  config,
   305→  network,
   306→  peerIdStr,
   307→  blockRoot,
   308→}: FetchByRootAndValidateBlockProps): Promise<SignedBeaconBlock> {
   309→  const response = await network.sendBeaconBlocksByRoot(peerIdStr, [blockRoot]);
   310→  const block = response.at(0)?.data;
   311→  if (!block) {
   312→    throw new DownloadByRootError({
   313→      code: DownloadByRootErrorCode.MISSING_BLOCK_RESPONSE,
   314→      peer: prettyPrintPeerIdStr(peerIdStr),
   315→      blockRoot: prettyBytes(blockRoot),
   316→    });
   317→  }
   318→  const receivedRoot = config.getForkTypes(block.message.slot).BeaconBlock.hashTreeRoot(block.message);
   319→  if (!byteArrayEquals(receivedRoot, blockRoot)) {
   320→    throw new DownloadByRootError(
   321→      {
   322→        code: DownloadByRootErrorCode.MISMATCH_BLOCK_ROOT,
   323→        peer: prettyPrintPeerIdStr(peerIdStr),
   324→        requestedBlockRoot: prettyBytes(blockRoot),
   325→        receivedBlockRoot: prettyBytes(toRootHex(receivedRoot)),
   326→      },
   327→      "block does not match requested root"
   328→    );
   329→  }
   330→  return block;
   331→}
   332→
   333→export async function fetchAndValidateBlobs({
   334→  network,
   335→  peerIdStr,
   336→  blockRoot,
   337→  block,
   338→  missing,
   339→}: FetchByRootAndValidateBlobsProps): Promise<deneb.BlobSidecars> {
   340→  const blobSidecars: deneb.BlobSidecars = await fetchBlobsByRoot({
   341→    network,
   342→    peerIdStr,
   343→    blockRoot,
   344→    missing,
   345→  });
   346→
   347→  await validateBlockBlobSidecars(block.message.slot, blockRoot, missing.length, blobSidecars);
   348→
   349→  return blobSidecars;
   350→}
   351→
   352→export async function fetchBlobsByRoot({
   353→  network,
   354→  peerIdStr,
   355→  blockRoot,
   356→  missing,
   357→  indicesInPossession = [],
   358→}: Pick<FetchByRootAndValidateBlobsProps, "network" | "peerIdStr" | "blockRoot" | "missing"> & {
   359→  indicesInPossession?: number[];
   360→}): Promise<deneb.BlobSidecars> {
   361→  const blobsRequest = missing
   362→    .filter((index) => !indicesInPossession.includes(index))
   363→    .map((index) => ({blockRoot, index}));
   364→  if (!blobsRequest.length) {
   365→    return [];
   366→  }
   367→  return await network.sendBlobSidecarsByRoot(peerIdStr, blobsRequest);
   368→}
   369→
   370→export async function fetchAndValidateColumns({
   371→  network,
   372→  peerMeta,
   373→  block,
   374→  blockRoot,
   375→  missing,
   376→}: FetchByRootAndValidateColumnsProps): Promise<WarnResult<fulu.DataColumnSidecars, DownloadByRootError>> {
   377→  const {peerId: peerIdStr} = peerMeta;
   378→  const slot = block.message.slot;
   379→  // TODO GLOAS: Get blob count from somewhere else since blobKzgCommitments is absent from block body
   380→  const blobCount = (block.message.body as BeaconBlockBody<ForkPostFulu & ForkPreGloas>).blobKzgCommitments.length;
   381→  if (blobCount === 0) {
   382→    return {result: [], warnings: null};
   383→  }
   384→
   385→  const blockRootHex = toRootHex(blockRoot);
   386→  const peerColumns = new Set(peerMeta.custodyColumns ?? []);
   387→  const requestedColumns = missing.filter((c) => peerColumns.has(c));
   388→  const columnSidecars = await network.sendDataColumnSidecarsByRoot(peerIdStr, [
   389→    {blockRoot, columns: requestedColumns},
   390→  ]);
   391→
   392→  const warnings: DownloadByRootError[] = [];
   393→
   394→  // it's not acceptable if no sidecar is returned with >0 blobCount
   395→  if (columnSidecars.length === 0) {
   396→    throw new DownloadByRootError({
   397→      code: DownloadByRootErrorCode.NO_SIDECAR_RECEIVED,
   398→      peer: prettyPrintPeerIdStr(peerIdStr),
   399→      slot,
   400→      blockRoot: blockRootHex,
   401→    });
   402→  }
   403→
   404→  // it's ok if only some sidecars are returned, we will try to get the rest from other peers
   405→  const requestedColumnsSet = new Set(requestedColumns);
   406→  const returnedColumns = columnSidecars.map((c) => c.index);
   407→  const returnedColumnsSet = new Set(returnedColumns);
   408→  const missingIndices = requestedColumns.filter((c) => !returnedColumnsSet.has(c));
   409→  if (missingIndices.length > 0) {
   410→    warnings.push(
   411→      new DownloadByRootError(
   412→        {
   413→          code: DownloadByRootErrorCode.NOT_ENOUGH_SIDECARS_RECEIVED,
   414→          peer: prettyPrintPeerIdStr(peerIdStr),
   415→          slot,
   416→          blockRoot: blockRootHex,
   417→          missingIndices: prettyPrintIndices(missingIndices),
   418→        },
   419→        "Did not receive all of the requested columnSidecars"
   420→      )
   421→    );
   422→  }
   423→
   424→  // check extra returned columnSidecar
   425→  const extraIndices = returnedColumns.filter((c) => !requestedColumnsSet.has(c));
   426→  if (extraIndices.length > 0) {
   427→    warnings.push(
   428→      new DownloadByRootError(
   429→        {
   430→          code: DownloadByRootErrorCode.EXTRA_SIDECAR_RECEIVED,
   431→          peer: prettyPrintPeerIdStr(peerIdStr),
   432→          slot,
   433→          blockRoot: blockRootHex,
   434→          invalidIndices: prettyPrintIndices(extraIndices),
   435→        },
   436→        "Received columnSidecars that were not requested"
   437→      )
   438→    );
   439→  }
   440→
   441→  await validateBlockDataColumnSidecars(slot, blockRoot, blobCount, columnSidecars);
   442→
   443→  return {result: columnSidecars, warnings: warnings.length > 0 ? warnings : null};
   444→}
   445→
   446→// TODO(fulu) not in use, remove?
   447→export async function fetchColumnsByRoot({
   448→  network,
   449→  peerMeta,
   450→  blockRoot,
   451→  missing,
   452→}: Pick<
   453→  FetchByRootAndValidateColumnsProps,
   454→  "network" | "peerMeta" | "blockRoot" | "missing"
   455→>): Promise<fulu.DataColumnSidecars> {
   456→  return await network.sendDataColumnSidecarsByRoot(peerMeta.peerId, [{blockRoot, columns: missing}]);
   457→}
   458→
   459→// TODO(fulu) not in use, remove?
   460→export type ValidateColumnSidecarsProps = Pick<
   461→  FetchByRootAndValidateColumnsProps,
   462→  "config" | "peerMeta" | "blockRoot" | "missing"
   463→> & {
   464→  slot: number;
   465→  blobCount: number;
   466→  needed?: fulu.DataColumnSidecars;
   467→  needToPublish?: fulu.DataColumnSidecars;
   468→};
   469→
   470→// TODO(fulu) not in use, remove?
   471→export async function validateColumnSidecars({
   472→  peerMeta,
   473→  slot,
   474→  blockRoot,
   475→  blobCount,
   476→  missing,
   477→  needed = [],
   478→  needToPublish = [],
   479→}: ValidateColumnSidecarsProps): Promise<void> {
   480→  const requestedIndices = missing;
   481→  const extraIndices: number[] = [];
   482→  for (const columnSidecar of needed) {
   483→    if (!requestedIndices.includes(columnSidecar.index)) {
   484→      extraIndices.push(columnSidecar.index);
   485→    }
   486→  }
   487→  if (extraIndices.length > 0) {
   488→    throw new DownloadByRootError(
   489→      {
   490→        code: DownloadByRootErrorCode.EXTRA_SIDECAR_RECEIVED,
   491→        peer: prettyPrintPeerIdStr(peerMeta.peerId),
   492→        slot,
   493→        blockRoot: prettyBytes(blockRoot),
   494→        invalidIndices: prettyPrintIndices(extraIndices),
   495→      },
   496→      "Received a columnSidecar that was not requested"
   497→    );
   498→  }
   499→  await validateBlockDataColumnSidecars(slot, blockRoot, blobCount, [...needed, ...needToPublish]);
   500→}
